// Renders the mesh defined by iChannel0 coords.

float glow(float t0, float t) { return pow(t0/max(0.0, 1.0 - t), 1.5); }

vec3 temp2rgb(float t) { t *= 1.88; return vec3(t, t*t*0.4, t*t*t*0.15); }

void mainImage(out vec4 o, in vec2 p) {
    vec2 pp = p/iResolution.xy;
    vec2 q = pp*2. - 1.;
    q *= iResolution.xy/iResolution.yy;

    o.rgb = vec3(0);

    if (pp.x < 0.5) {
        float t = texture(iChannel1, vec2(0.5, 1.0) - pp).r;
        vec3 c = temp2rgb(2.*abs(t));
        if (t < 0.) c = c.bgr;
        o.rgb += c;
    }

    if (pp.x > 0.5) {
        float t = texture(iChannel1, pp - vec2(0.5, 0.0)).g;
        o.rgb += temp2rgb(t);
    }

    o.rgb *= smoothstep(0.0, 0.05, abs(pp.x - 0.5));

    vec4 ch2 = texture(iChannel2, pp);
    o.rgb += temp2rgb(pow(R0/ch2.r, 1.5));
    o.rgb += temp2rgb(pow(R0/ch2.g, 1.5));

    o.a = 1.0;
}

const float PI = radians(180.);
const float SQ3 = sqrt(3.);
const float INF = 1e10;

// Simulation consts
const int N = 64; // 16, 32 or 64 in the Fermi-Pasta-Ulam problem
const float EXP = 1.0;
const float MASS = 2.0;

// Rendering consts
const float R0 = 0.003;
const float DMAX = 2.0;

vec4 texFetch(sampler2D ch0, int i) {
    i = int(mod(float(i), float(N)));
    return texelFetch(ch0, ivec2(i,0), 0);
}

vec2 iexp(float phi) {
    return vec2(cos(phi), sin(phi));
}

vec2 imul(vec2 a, vec2 b) {
    return vec2(a.x*b.x - a.y*b.y, a.x*b.y + a.y*b.x);
}

void swap(inout vec2[N] a, int i, int j) {
    vec2 ai = a[i]; a[i] = a[j]; a[j] = ai;
}

// Simulates the motion of masses in iChannel0.

void mainImage(out vec4 o, in vec2 p) {
    ivec2 pp = ivec2(p - 0.5);

    if (pp.x > N-1 || pp.y > 0)
        return;

    if (iFrame == 0) {
        float x = 2.*PI*(float(pp.x)+0.5)/float(N);
        o = vec4(0);
        o.x = 0.35*cos(x*1.);
        o.z = o.x;
        return;
    }

    vec4 cc = texFetch(iChannel0, pp.x); // .xy=curr, .zw=prev
    vec2 rr = texFetch(iChannel0, pp.x + 1).xy;
    vec2 ll = texFetch(iChannel0, pp.x - 1).xy;

    // https://en.wikipedia.org/wiki/Toda_lattice
    vec2 T = exp(EXP*(ll - cc.xy)) - exp(EXP*(cc.xy - rr));

    o.xy = 2.*cc.xy - cc.zw + T/MASS; // Newton's 2nd law
    o.zw = cc.xy; // prev <- curr
    o = clamp(o,vec4(-DMAX),vec4(DMAX));

    if (iMouse.z > 0.) {
        vec2 r = iResolution.xy;
        vec2 m = iMouse.xy/r;
        if (int(m.y*float(N) - 0.5) == pp.x)
            o.x = r.x/r.y*(m.x*2. - 1.);
    }
}

// Records the oscillator state and its spectrum in iChannel1.

vec4[N] fetchData() {
    vec4[N] a;
    for (int i = 0; i < N; i++)
        a[i] = texFetch(iChannel0, i);
    return a;
}

vec2 interpolate(vec2[N] a, float x) {
    int i = int(floor(x)) % N, j = int(ceil(x)) % N;
    return mix(a[i], a[j], smoothstep(0., 1., fract(x)));
}

void fft_rev(inout vec2[N] a) {
  for (int i = 1, j = 0; i < N; i++) {
    int b = N >> 1;
    while (j >= b)
      j -= b, b >>= 1;
    j += b;
    if (i < j)
        swap(a, i, j);
  }
}

void fft_mix(inout vec2[N] a, int s) {
  vec2 e = iexp(2.*PI/float(s));

  for (int i = 0; i < N; i += s) {
    vec2 w = vec2(1,0);

    for (int j = 0; j < s/2; j++) {
      int u = i + j, v = i + j + s/2;
      vec2 vw = imul(a[v], w);
      a[v] = a[u] - vw;
      a[u] = a[u] + vw;
      w = imul(w, e);
    }
  }
}

void fft(inout vec2[N] a) {
    fft_rev(a);
    for (int s = 2; s <= N; s *= 2)
        fft_mix(a, s);
}

vec2[N] spectrum(vec2[N] a) {
    fft(a); // a=FFT(a)
    for (int i = 0; i < N; i++)
        a[i] = dot(a[i],a[i])/float(N) * vec2(1,0);
     return a;
}

vec2[N] string(vec4[N] a) {
    vec2[N] b;
    for (int i = 0; i < N; i++)
        b[i] = vec2(a[i].x, 0);
    return b;
}

void mainImage(out vec4 o, vec2 p) {
    if (iFrame > 0)
        o.rg = texelFetch(iChannel1, ivec2(p-0.5) - ivec2(1,0), 0).rg;

    if (p.x < 1.) {
        vec4[N] ch0 = fetchData();
        vec2[N] a = string(ch0);
        vec2[N] sa = spectrum(a);

        float i = p.y/iResolution.y*float(N);

        o.r = interpolate(a, i).x/DMAX;
        o.g = sqrt(interpolate(sa, i+float(N/2)).x);
    }
}

// Renders the mesh defined by iChannel0 coords.

float lineSDF(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p-a, ba = b-a;
    float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
    return length( pa - ba*h );
}

float i2y(int i) { return (float(i) + 0.5)/float(N) * 2. - 1.; }
float i2x(int i) { return texFetch(iChannel0, i).x; }
vec2 i2xy(int i) { return vec2(i2x(i), i2y(i)); }

float stringSDF(vec2 q) {
    float d = INF;

    for (int i = 0; i < N; i++) {
        if (abs(i2y(i) - q.y) > 2.0/float(N))
            continue;

        vec2 a = i2xy(i), b = i2xy(i-1);
        if (abs(q.x - a.x) > abs(b.x - a.x) + 1.0/float(N))
            continue;

        d = min(d, lineSDF(q, a, b));
    }

    return d;
}

float phaseSDF(vec2 q) {
    float d = INF;

    for (int i = 0; i < N; i++) {
        vec4 r = texFetch(iChannel0, i);
        float y = (float(i) + 0.5)/float(N) * 2. - 1.;
        vec2 c = vec2(r.x, r.x - r.z)*vec2(1,1); // (x, dx/dt)
        d = min(d, length(q - c));
    }

    return d;
}

vec2 pp2q(vec2 pp) {
    return (pp*2. - 1.) * iResolution.xy/iResolution.yy;
}

void mainImage(out vec4 o, vec2 p) {
    vec2 pp = p/iResolution.xy;
    vec2 q = pp2q(pp);

    o.rg = vec2(INF);

    if (abs(q.x) < DMAX)
        o.r = stringSDF(q);

    vec2 dp = 0.4/vec2(iResolution.x/iResolution.y, 1.);

    if (pp.x > 1. - dp.x && pp.y > 1. - dp.y) {
        vec2 q2 = pp2q((pp - 1. + dp)/dp)*dp;
        o.g = phaseSDF(q2);
    }
}
